import itertools

def primos():
    numero = 2
    while True:
        eh_primo = True
        for divisor in range(2, int(numero ** 0.5) + 1):
            if numero % divisor == 0:
                eh_primo = False
                break
        if eh_primo:
            yield numero
        numero += 1

print(list(itertools.islice(primos(), 5)))
